    GameUtils.BindRedPoint(Constants.RedPointConst.RankCollectionReward, self.RT_BtnDrawReward:Find("Under").gameObject, true)
    -- 奖励按钮
    local hasReward = GameUtils.GetRedPointNum(Constants.RedPointConst.RankCollectionReward)
    if hasReward > 0 then
        UIEventProxy.Create(self.RT_BtnDrawReward:Find("Area").gameObject).onPointerClick = Bind(self, self.OnBtnRewards)
        KTool.SetActive(self.RT_BtnDrawReward:Find("Under/UIFX_ReceiveAward"), true)
    end
end

function RankCollectionDialog:RequestHome()
    local succees = false
    GameUtils.Request(Interfaces.OverseaRankCollectionHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succees = true
        self.dojo = response.data
        -- print("[排行榜聚合页] home", table.dump(self.dojo, nil, 2))
    end)

    while not succees do
        cs_coroutine.yield_return()
    end
end

function RankCollectionDialog:OnBtnRewards()
    GameUtils.SetRedPointNum(Constants.RedPointConst.RankCollectionReward, 0)
    GameUtils.CommonDrawRewards(Interfaces.OverseaRankCollectionDrawRewards, nil, {{id = Constants.UITypeIds.OverseaRankPageDialog}})
end

function RankCollectionDialog:GetBtnDojo(btnName)
    return self.dojo[btnName]
end

function RankCollectionDialog:GetBtnNode(groupIndex, index)
    local btnGroupNode = self.btnNodes[groupIndex]
    if isNull(index) then
        return btnGroupNode
    else
        return btnGroupNode.subs[index]
    end
end

function RankCollectionDialog:InitBtnPage(pageData)
    for i, btnGroupInfo in ipairs(pageData) do
        if isNotNull(btnGroupInfo.subs) then
            -- 按钮组
            local btnGroupNode = self:GetBtnNode(i)
            self:SetBtnGroupData(btnGroupInfo, btnGroupNode.btn)
            for j, btnInfo in ipairs(btnGroupInfo.subs) do
                local btnNode = self:GetBtnNode(i, j)
                local btnDojo = self:GetBtnDojo(btnInfo.name)
                self:SetBtnData(btnInfo, btnNode.btn, btnDojo)
            end
        else
            -- 按钮
            local btnInfo = btnGroupInfo
            local btnNode = self:GetBtnNode(i)
            local btnDojo = self:GetBtnDojo(btnInfo.name)
            self:SetBtnData(btnInfo, btnNode.btn, btnDojo)
        end
    end
end

function RankCollectionDialog:SetBtnGroupData(btnGroupInfo, btnGroup)
    local vo = CfUtils.SystemToggleVo( btnGroupInfo.id)
    local groupName = vo.realName
    local RT_TxtName = btnGroup:Find("BtnNode/Title/TextName")
    if isNotNull(RT_TxtName) then
        local Txt_Name = RT_TxtName:GetComponent(typeof(Text))
        Txt_Name.text = groupName
    end
end

function RankCollectionDialog:SetBtnData(btnInfo, btn, btnDojo)
    local title = ""
    if btnInfo.title == 1 then
        local vo = CfUtils.SystemToggleVo( btnInfo.id)
        title = vo.realName
    elseif btnInfo.title == 2 then
        title = localize("战区_num_", {_num_ = btnDojo.zoneId})
    end

    -- 按钮子标题
    local zone = btn.transform:Find("BtnNode/TextBranch"):GetComponent(typeof(Text))
    zone.text = title

    -- 异步PVP的Dojo结构特殊
    if btnInfo.name == "async"
    or btnInfo.name == "asyncSingle" then
        btnDojo = btnDojo.firstPlace
    end

    if isNull(btnDojo) then return end

    local trans = btn.transform:Find("BtnNode")
    local btnAreaTrans = trans:Find("Area")
    local onRankTrans = trans:Find("StatusRank/OnRank")
    local emptyTrans = trans:Find("StatusRank/EmotyRank")
    local playerNameTrans = onRankTrans:Find("Bg/TextName")
    local playerHeadTrans = onRankTrans:Find("Head/CommonPlayerHeadNode")

    KTool.SetActive(emptyTrans, false)
    KTool.SetActive(onRankTrans, true)

    -- 玩家名字
    local playerName = playerNameTrans:GetComponent(typeof(Text))
    playerName.text = btnDojo.name

    -- 头像，头像框
    local LB_PlayerHead = GetLuaBehaviour(playerHeadTrans.gameObject, PlayerHeadNodeLuaPath)
    LB_PlayerHead.Env:FreshAvatarFrame(btnDojo.avatar, btnDojo.avatarFrame)

    -- 点击头像显示玩家信息
    LB_PlayerHead.Env:SetCallBack(function()
        if btnDojo.playerId < 0 then return end
        if btnDojo.playerId == GameUtils.GetPlayerId() then return end


        -- 直接进入 他人的 个人信息界面2D版 
        GameUtils.ShowPlayerInfo( btnDojo.playerId, 
            {  
                { id = Constants.UITypeIds.OverseaRankPageDialog}
            } 
        )
        -- 下方为旧方案, 暂被替代:
        -- GameUtils.ShowCommonPlayerHeadOption(playerHeadTrans.gameObject, Constants.PlayerHeadOptionType.Common,{
        --     playerId    = btnDojo.playerId,
        --     name        = btnDojo.name,
        --     level       = btnDojo.level,
        --     avatar      = btnDojo.avatar,
        --     avatarFrame = btnDojo.avatarFrame,
        --     exclude = {
        --         { id = Constants.UITypeIds.OverseaRankPageDialog}
        --     }
        -- })
    end)

    -- 点击区域跳转排行榜
    UIEventProxy.Create(btnAreaTrans.gameObject).onPointerClick = function()
        self:JumpToRankDialog(btnInfo.id)
    end
end

function RankCollectionDialog:JumpToRankDialog(systemId)
    if systemId == Constants.SystemToggleIds.Id2008 then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionRankDialog), {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id2007 then
        UIModule.OpenDialog(
            {id = Constants.UITypeIds.LadderStruggleRankDialog, parameters = {systemName = Constants.SystemToggleIds.Id2007}}, 
            {{id = Constants.UITypeIds.OverseaRankPageDialog}}
        )
    elseif systemId == Constants.SystemToggleIds.Id2017 then
        UIModule.OpenDialog(
            { id = Constants.UITypeIds.LadderStruggleSingleRankDialog, parameters = {systemName = Constants.SystemToggleIds.Id2017} }, 
            {{id = Constants.UITypeIds.OverseaRankPageDialog}}
        )
    elseif systemId == Constants.SystemToggleIds.Id3001 then
        local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCattyRank ,parameters = { type = MaidCoffeeConstants.CoffeeRankType.CafeTipRank } }, {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id2011 then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaTowerRankDialog, { type = 1 }), {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id2012 then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaTowerRankDialog, { type = 2 }), {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id2013 then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaTowerRankDialog, { type = 3 }), {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id2014 then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaTowerRankDialog, { type = 4 }), {{id = Constants.UITypeIds.OverseaRankPageDialog}})
    elseif systemId == Constants.SystemToggleIds.Id14 then
        local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
        worldBossComponent:OnWorldBossEnter()
    end
end

return RankCollectionDialog
